DEGRAU = "Degrau sistêmico"
OUTRA_VIGENCIA = "Taxa de outra vigência"
NAO_DETERMINADA = "Não determinada"

PRODUTOS_CREDITO = ("credito_vista", "credito_2a6", "credito_7a12")
NOME_PRODUTO = {
    "debito": "débito",
