def _taxa(frac: Decimal) -> str:
    return f"{(frac * 100).quantize(Decimal('0.01'))}".replace(".", ",") + "%"


def _data(d: dt.date, ano: bool = True) -> str:
    return d.strftime("%d/%m/%Y" if ano else "%d/%m")


def _periodo(ini: dt.date, fim: dt.date) -> str:
    if ini == fim:
