    produtos = sorted(set(linhas["produto"]), key=list(NOME_PRODUTO).index)
    delta = linhas.apply(_desvio, axis=1).iloc[0]
    ini = linhas["data_referencia"].min()
    if set(produtos) == set(PRODUTOS_CREDITO):
