    ordem = sorted(por_causa, key=lambda kv: (-sum(kv[1]["divergencia"], Decimal(0)), kv[0]))
    textos = []
    for causa, linhas in ordem:
        if causa == DEGRAU:
            txt = _texto_degrau(linhas, linhas_df[linhas_df["cnpj"] == cnpj])
