    linhas = _linhas([("credito_vista", 12, "0.0249", "0.0299", 1)])
    assert cc.classificar(linhas, {"ec": [_entry(1)]}) == {"T0": cc.NAO_DETERMINADA}


def test_linha_correta_dentro_da_janela_desfaz_o_degrau():
    linhas = _linhas([("credito_vista", 12, "0.0249", "0.0299", 1),
